    private void logRequestResponseData(String url, EupravaRequest request, EupravaResponse response) throws SQLException {
        logger.info("Logging za request ");
        try (Connection connection = DriverManager.getConnection
                (databaseUrl, databaseUser, databasePassword)
        ) {
            String sql = "INSERT INTO TBL_MPMB_LOGGING (LOG_TIMESTAMP, URL, UNIQUETRANSACTIONID, REQUEST_MESSAGE, RETURN_CODE,RESPONSE_MESSAGE) " +
                    "VALUES (?, ?, ?, ?, ?, ?)";
            try (PreparedStatement statement = connection.prepareStatement(sql)) {
                statement.setTimestamp(1, new java.sql.Timestamp(System.currentTimeMillis()));
                statement.setString(2, url);
                statement.setString(3, request.getUniqueTransactionId());
                String requestString = serialize_Euprava_Request_ToJson(request);
                Reader requestBodyReader = new StringReader(requestString);
                statement.setCharacterStream(4, requestBodyReader, requestString.length());
                statement.setString(5, response.getSuccess());
                String responseString = serialize_Euprava_Response_ToJson(response);
                Reader responseBodyReader = new StringReader(responseString);
                statement.setCharacterStream(6, responseBodyReader, responseString.length());

                statement.executeUpdate();
                connection.close();
            } catch (IOException e) {
                e.printStackTrace();
                connection.close();
            }
        }
    }
