            LocalDate vremeVazenja = vremePrijema.plusDays(piuw_validnost_podataka);
            Date podaciValidniDo = Date.valueOf(vremeVazenja);
            response.setPodaciValidniDo(podaciValidniDo);

            logger.info("ResultSet closed");
            conection.close();
            logger.info("ResultSet closed");

        } catch (Exception e) {
            responseHeader.setSuccess("N");
            response.setResponseHeader(responseHeader);
            response.setJmbg(jmbg);
            response.setCoreid(coreid);
            response.setUniqueTransactionId(uniquetransactionid);
            responseHeader.setErrorMessage("Za trazenog klijenta ne nalazimo podatke!");
//            responseHeader.setErrorMessage("greska: "+e.toString());
            response.setResponseHeader(responseHeader);
            logger.info("greska u eUpravaForPIUW : " + e);
            conection.close();
            logger.info("ResultSet closed u catch-u");

        }
        finally {
            conection.close();
            logger.info("ResultSet closed in finally!");
        }
        logRequestResponseeUpravaData(url,REQ,response);
        return response;
    }
    @PostMapping("/UBSData")
    public UBSDataResponse getAllUBSData(@RequestBody UBSRequest req, HttpServletRequest request) throws SQLException {
        logger.info("Usao je u UBSData, JMBg: ");
        logger.info(req.getJmbg());
        String url = request.getRequestURL().toString();

        UBSDataResponse response = new UBSDataResponse();
        response.setResponseHeader(buildResponseHeader(req.getRequestHeader()));

        String uniqueSerialNumber = req.getJmbg();
        if (uniqueSerialNumber == null || uniqueSerialNumber.trim().isEmpty()) {
            response.getResponseHeader().setSuccess("N");
            response.getResponseHeader().setErrorMessage("JMBG nije prosleÄ‘en.");
            logRequestResponseeUBSData(url, req, response);
            return response;
        }

        try (Connection connection = DriverManager.getConnection(databaseUrl, databaseUser, databasePassword)) {

            UbsRequesterDto requester = ubsService.getUBSRequesterByUniqueSerialNumber(uniqueSerialNumber, connection);
            if (requester == null || requester.getRequestId() == null) {
                response.getResponseHeader().setSuccess("N");
                response.getResponseHeader().setErrorMessage("Nije pronaÄ‘en korisnik sa datim JMBG.");
                logRequestResponseeUBSData(url, req, response);
                return response;
            }

            String requestId = requester.getRequestId();

            UBSResponse responseSingle = new UBSResponse();
            responseSingle.setUbsRequester(mapRequester(
                    ubsService.getUBSRequesterByRequestId(requestId, connection),
                    ubsService.getUBSEmploymentStatusByRequestId(requestId, connection),
                    ubsService.getUbsRetirementStatusByRequestId(requestId, connection)
            ));
            responseSingle.setEmployer(ubsService.getUBSEmployerByRequestId(requestId, connection));
            responseSingle.setFinancialData(mapFinancialData(
                    ubsService.getUbsFinancialDataByRequestId(requestId, connection),
                    ubsService.getUbsIncomeSummaryByRequestId(requestId, connection),
                    ubsService.getUbsIncomeDetailsByRequestId(requestId, connection),
                    ubsService.getUbsOtherIncomeByRequestId(requestId, connection)
            ));

            response.setUbsResponses(Collections.singletonList(responseSingle));
            response.getResponseHeader().setSuccess("Y");
            logRequestResponseeUBSData(url, req, response);

        } catch (Exception e) {
            logger.error("GreÅ¡ka tokom obrade UBS podataka", e);
            response.getResponseHeader().setSuccess("N");
            response.getResponseHeader().setErrorMessage("DoÅ¡lo je do greÅ¡ke prilikom obrade zahteva.");
            logRequestResponseeUBSData(url, req, response);
        }

        return response;
    }

    private PIUWResponseHeader buildResponseHeader(PIUWRequestHeader header) {
        PIUWResponseHeader responseHeader = new PIUWResponseHeader();
        responseHeader.setSourceApp(header.getSourceApp());
        responseHeader.setUserId(header.getUserId());
        responseHeader.setOpu(header.getOpu());
        responseHeader.setRequestCode(header.getRequestCode());
        responseHeader.setSuccess("Y");
        return responseHeader;
    }

    private UbsRequester mapRequester(UbsRequesterDto dto, UbsEmploymentStatus employmentStatus, UbsRetirementStatus retirementStatus) {
        UbsRequester requester = new UbsRequester();
        requester.setRequestId(dto.getRequestId());
        requester.setContractNumber(dto.getContractNumber());
        requester.setUniqueSerialNumber(dto.getUniqueSerialNumber());
        requester.setFullName(dto.getFullName());
        requester.setQualificationCode(dto.getQualificationCode());
        requester.setQualificationName(dto.getQualificationName());
        requester.setWorkplaceName(dto.getWorkplaceName());
        requester.setGender(dto.getGender());
        requester.setInsuranceCode(dto.getInsuranceCode());
        requester.setInsuranceName(dto.getInsuranceName());
        requester.setRequesterIncomeCode(dto.getRequesterIncomeCode());
        requester.setTotalElapsedTimeInService(dto.getTotalElapsedTimeInService());
        requester.setLastChangeDate(dto.getLastChangeDate());
        requester.setType(dto.getType());
        requester.setCreatedAt(dto.getCreatedAt());

        requester.setEmploymentStatus(employmentStatus);
        requester.setRetirementStatus(retirementStatus);

        return requester;
    }

    private UbsFinancialData mapFinancialData (UbsFinancialDataDto dto, List<UbsIncomeSummaryDto> ubsIncomeSummaryDto, List<UbsIncomeDetailsDto> ubsIncomeDetailsDto, List<UbsOtherIncome>  ubsOtherIncomeList) {
        UbsFinancialData ubsFinancialData = new UbsFinancialData();
        ubsFinancialData.setForPeriodInMonths(dto.getForPeriodInMonths());
        ubsFinancialData.setIsMaxIncome(dto.getIsMaxIncome());
        ubsFinancialData.setNote(dto.getNote());

        List<UbsIncomeSummary> transformedListSummary = new ArrayList<>();
        List<UbsIncomeDetail> transformedListDetail = new ArrayList<>();

        for (UbsIncomeSummaryDto summaryDto : ubsIncomeSummaryDto) {
            UbsIncomeSummary summary = mapIncomeSummary(summaryDto);
            transformedListSummary.add(summary);
        }

        for (UbsIncomeDetailsDto detailsDtoDto : ubsIncomeDetailsDto) {
            UbsIncomeDetail detail = mapIncomeDetail(detailsDtoDto);
            transformedListDetail.add(detail);
        }


        UbsIncome ubsIncome=new UbsIncome();
        ubsIncome.setUbsIncomeSummaryList(transformedListSummary);
        ubsIncome.setUbsIncomeDetailList(transformedListDetail);

        ubsFinancialData.setIncome(ubsIncome);

        ubsFinancialData.setOtherIncomeList(ubsOtherIncomeList);


        return ubsFinancialData;
    }
    private UbsIncomeSummary mapIncomeSummary (UbsIncomeSummaryDto dto) {
        UbsIncomeSummary ubsIncomeSummary= new UbsIncomeSummary();
        ubsIncomeSummary.setPeriodInMonths(dto.getPeriodInMonths());
        ubsIncomeSummary.setGross(dto.getGross());
        ubsIncomeSummary.setNet(dto.getNet());
        ubsIncomeSummary.setGrossavarage(dto.getGrossAverage());
        ubsIncomeSummary.setNetavarage(dto.getNetAverage());

        return ubsIncomeSummary;
    }
    private UbsIncomeDetail mapIncomeDetail (UbsIncomeDetailsDto dto) {
        UbsIncomeDetail ubsIncomeDetail= new UbsIncomeDetail();
        ubsIncomeDetail.setYear(dto.getYear());
        ubsIncomeDetail.setMonth(dto.getMonth());
        ubsIncomeDetail.setMonthName(dto.getMonthName());
        ubsIncomeDetail.setGross(dto.getGross());
        ubsIncomeDetail.setNet(dto.getNet());
        ubsIncomeDetail.setType(dto.getType());

        return ubsIncomeDetail;
    }

    /*
       Metoda za logovanje requesta/response-a za servis /UBSData
    */
    private void logRequestResponseeUBSData(String url, UBSRequest request, UBSDataResponse response) throws SQLException {
        logger.info("Logging za logRequestResponseeUBSData ");
        try (Connection connection = DriverManager.getConnection
                (databaseUrl, databaseUser, databasePassword)
        ) {
            String sql = "INSERT INTO TBL_UBS_DATA_LOGGING (LOG_TIMESTAMP, URL, SOURCEAPP, REQUEST_CODE, JMBG, REQUEST_MESSAGE, SUCCESS,RESPONSE_MESSAGE) " +
                    "VALUES (?, ?, ?, ?, ?, ?, ?, ?)";
            try (PreparedStatement statement = connection.prepareStatement(sql)) {
                statement.setTimestamp(1, new java.sql.Timestamp(System.currentTimeMillis()));
                statement.setString(2, url);
                statement.setString(3, request.getRequestHeader().getSourceApp());
                statement.setString(4, request.getRequestHeader().getRequestCode());
                statement.setString(5, request.getJmbg());

                String requestString = serialize_UBS_Data_Request_ToJson(request);
                Reader requestBodyReader = new StringReader(requestString);
                statement.setCharacterStream(6, requestBodyReader, requestString.length());
                statement.setString(7, response.getResponseHeader().getSuccess());
                String responseString = serialize_UBS_Data_Response_ToJson(response);
                Reader responseBodyReader = new StringReader(responseString);
                statement.setCharacterStream(8, responseBodyReader, responseString.length());

                statement.executeUpdate();
                connection.close();
            } catch (IOException e) {
                e.printStackTrace();
                connection.close();
            }
        }
    }


