package rs.unicreditbank.ucbservices.ecs.service.impl;

import com.fasterxml.jackson.databind.MapperFeature;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.core.io.Resource;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.http.HttpEntity;
import org.springframework.http.HttpHeaders;
import org.springframework.http.HttpMethod;
import org.springframework.http.MediaType;
import org.springframework.http.ResponseEntity;
import org.springframework.stereotype.Service;
import org.springframework.http.client.SimpleClientHttpRequestFactory;
import org.springframework.http.converter.HttpMessageConverter;
import org.springframework.http.converter.json.MappingJackson2HttpMessageConverter;
import org.springframework.web.client.RestClientException;
import org.springframework.web.client.RestTemplate;
import rs.unicreditbank.ucbservices.ecs.dto.B2BRequestCreateRequest;
import rs.unicreditbank.ucbservices.ecs.dto.B2BRequestCreateResponse;
import rs.unicreditbank.ucbservices.ecs.dto.B2BRequestStatusResponse;
import rs.unicreditbank.ucbservices.ecs.dto.B2BReportJsonResponse;
import rs.unicreditbank.ucbservices.ecs.dto.B2BReportPdfResponse;
import rs.unicreditbank.ucbservices.ecs.service.EcsWebApiService;

import javax.net.ssl.HttpsURLConnection;
import javax.net.ssl.KeyManager;
import javax.net.ssl.KeyManagerFactory;
import javax.net.ssl.SSLContext;
import javax.net.ssl.TrustManagerFactory;
import javax.net.ssl.TrustManager;
import javax.net.ssl.X509TrustManager;
import javax.net.ssl.HostnameVerifier;
import java.io.InputStream;
import java.net.Authenticator;
import java.net.HttpURLConnection;
import java.net.InetSocketAddress;
import java.net.PasswordAuthentication;
import java.net.Proxy;
import java.security.KeyStore;
import java.security.cert.CertificateFactory;
import java.security.cert.CertificateException;
import java.security.cert.X509Certificate;
import java.util.List;

@Service
public class EcsWebApiServiceImpl implements EcsWebApiService {
    private static final Logger log = LoggerFactory.getLogger(EcsWebApiServiceImpl.class);

    @Value("${ecs.proxy.request-base-url:https://test.ecs.services/gateway/o/api}")
    private String requestBaseUrl;

    @Value("${ecs.proxy.report-base-url:https://test.ecs.services/gateway/r/api}")
    private String reportBaseUrl;

    @Value("${ecs.proxy.default-tenant-id:}")
    private String defaultTenantId;

    @Value("${ecs.proxy.default-api-key:}")
    private String defaultApiKey;

    @Value("${ecs.ssl.enabled:true}")
    private boolean ecsSslEnabled;

    @Value("${ecs.ssl.protocol:TLSv1.2}")
    private String ecsSslProtocol;

    @Value("${ecs.ssl.trust-cert:classpath:UniCredit.crt}")
    private Resource ecsTrustCert;

    @Value("${ecs.ssl.mtls.enabled:false}")
    private boolean ecsMtlsEnabled;

    @Value("${ecs.ssl.keystore.path:classpath:ucb_keystore.jks}")
    private Resource ecsKeyStore;

    @Value("${ecs.ssl.keystore.password:}")
    private String ecsKeyStorePassword;

    @Value("${ecs.ssl.timeout.connect-ms:15000}")
    private int connectTimeoutMs;

    @Value("${ecs.ssl.timeout.read-ms:30000}")
    private int readTimeoutMs;

    @Value("${ecs.ssl.insecure-skip-verify:false}")
    private boolean insecureSkipVerify;

    @Value("${ecs.http.proxy.enabled:false}")
    private boolean proxyEnabled;

    @Value("${ecs.http.proxy.host:}")
    private String proxyHost;

    @Value("${ecs.http.proxy.port:0}")
    private int proxyPort;

    @Value("${ecs.http.proxy.username:}")
    private String proxyUsername;

    @Value("${ecs.http.proxy.password:}")
    private String proxyPassword;

    private RestTemplate restTemplate;

    @jakarta.annotation.PostConstruct
    public void initRestTemplate() {
        log.info("ECS client config: sslEnabled={}, insecureSkipVerify={}, mtlsEnabled={}, proxyEnabled={}, proxyHost={}, proxyPort={}",
                ecsSslEnabled, insecureSkipVerify, ecsMtlsEnabled, proxyEnabled, proxyHost, proxyPort);
        if (!ecsSslEnabled) {
            buildRequestFactoryWithoutSsl();
            return;
        }

        SSLContext sslContext = insecureSkipVerify ? createInsecureSslContext() : createSslContext();
        HostnameVerifier hostnameVerifier = insecureSkipVerify ? (hostname, session) -> true : null;
        SimpleClientHttpRequestFactory factory = new SimpleClientHttpRequestFactory() {
            @Override
            protected void prepareConnection(HttpURLConnection connection, String httpMethod) {
                try {
                    super.prepareConnection(connection, httpMethod);
                } catch (java.io.IOException e) {
                    throw new IllegalStateException("Cannot prepare ECS HTTPS connection", e);
                }
                if (connection instanceof HttpsURLConnection httpsConnection) {
                    httpsConnection.setSSLSocketFactory(sslContext.getSocketFactory());
                    if (hostnameVerifier != null) {
                        httpsConnection.setHostnameVerifier(hostnameVerifier);
                    }
                }
            }
        };
        configureFactoryWithTimeoutAndProxy(factory);
        this.restTemplate = buildCaseInsensitiveRestTemplate(factory);
    }

    @Override
    public B2BRequestCreateResponse createRequest(B2BRequestCreateRequest request) {
        String url = requestBaseUrl + "/v2/B2BRequest/request";
        HttpEntity<B2BRequestCreateRequest> entity = new HttpEntity<>(request, buildHeaders());
        return exchange(url, HttpMethod.POST, entity, B2BRequestCreateResponse.class);
    }

    @Override
    public B2BRequestStatusResponse getStatus(String requestId) {
        String url = requestBaseUrl + "/B2BRequest/status/" + requestId;
        HttpEntity<Void> entity = new HttpEntity<>(buildHeaders());
        return exchange(url, HttpMethod.GET, entity, B2BRequestStatusResponse.class);
    }

    @Override
    public B2BReportJsonResponse getReport(String requestId) {
        String url = reportBaseUrl + "/B2BReport/json-payload/" + requestId;
        HttpEntity<Void> entity = new HttpEntity<>(buildHeaders());
        return exchange(url, HttpMethod.GET, entity, B2BReportJsonResponse.class);
    }

    @Override
    public B2BReportPdfResponse getPdfReport(String requestId) {
        String url = reportBaseUrl + "/B2BReport/pdf-report/" + requestId;
        HttpEntity<Void> entity = new HttpEntity<>(buildHeaders());
        return exchange(url, HttpMethod.GET, entity, B2BReportPdfResponse.class);
    }

    private HttpHeaders buildHeaders() {
        HttpHeaders headers = new HttpHeaders();
        headers.setContentType(MediaType.APPLICATION_JSON);
        headers.set("X-Tenant-Id", resolveCredential(defaultTenantId, "X-Tenant-Id"));
        headers.set("X-API-Key", resolveCredential(defaultApiKey, "X-API-Key"));
        return headers;
    }

    private String resolveCredential(String configuredValue, String headerName) {
        if (configuredValue != null && !configuredValue.isBlank()) {
            return configuredValue;
        }
        throw new IllegalStateException("Missing credential for header: " + headerName);
    }

    private <T> T exchange(String url, HttpMethod method, HttpEntity<?> entity, Class<T> responseType) {
        try {
            ResponseEntity<T> response = restTemplate.exchange(url, method, entity, responseType);
            return response.getBody();
        } catch (RestClientException e) {
            throw new IllegalStateException("ECS proxy call failed for URL: " + url + ". Error: " + e.getMessage(), e);
        }
    }

    private SSLContext createInsecureSslContext() {
        try {
            TrustManager[] trustAll = new TrustManager[]{new X509TrustManager() {
                @Override
                public void checkClientTrusted(X509Certificate[] chain, String authType) {
                }

                @Override
                public void checkServerTrusted(X509Certificate[] chain, String authType) {
                }

                @Override
                public X509Certificate[] getAcceptedIssuers() {
                    return new X509Certificate[0];
                }
            }};
            SSLContext sslContext = SSLContext.getInstance(ecsSslProtocol);
            sslContext.init(null, trustAll, new java.security.SecureRandom());
            return sslContext;
        } catch (Exception e) {
            throw new IllegalStateException("Failed to initialize insecure ECS SSL context", e);
        }
    }

    private SSLContext createSslContext() {
        try {
            KeyStore trustStore = KeyStore.getInstance(KeyStore.getDefaultType());
            trustStore.load(null, null);

            try (InputStream certInput = ecsTrustCert.getInputStream()) {
                X509Certificate cert = (X509Certificate) CertificateFactory.getInstance("X.509").generateCertificate(certInput);
                trustStore.setCertificateEntry("ecs-trust-cert", cert);
            }

            TrustManagerFactory trustManagerFactory = TrustManagerFactory.getInstance(TrustManagerFactory.getDefaultAlgorithm());
            trustManagerFactory.init(trustStore);
            TrustManagerFactory defaultTrustManagerFactory = TrustManagerFactory.getInstance(TrustManagerFactory.getDefaultAlgorithm());
            defaultTrustManagerFactory.init((KeyStore) null);

            KeyManager[] keyManagers = null;
            if (ecsMtlsEnabled) {
                if (ecsKeyStorePassword == null || ecsKeyStorePassword.isBlank()) {
                    throw new IllegalStateException("ecs.ssl.keystore.password must be set when ecs.ssl.mtls.enabled=true");
                }
                KeyStore keyStore = KeyStore.getInstance("JKS");
                try (InputStream keyStoreInput = ecsKeyStore.getInputStream()) {
                    keyStore.load(keyStoreInput, ecsKeyStorePassword.toCharArray());
                }
                KeyManagerFactory keyManagerFactory = KeyManagerFactory.getInstance(KeyManagerFactory.getDefaultAlgorithm());
                keyManagerFactory.init(keyStore, ecsKeyStorePassword.toCharArray());
                keyManagers = keyManagerFactory.getKeyManagers();
            }

            SSLContext sslContext = SSLContext.getInstance(ecsSslProtocol);
            X509TrustManager defaultTm = extractX509TrustManager(defaultTrustManagerFactory.getTrustManagers());
            X509TrustManager customTm = extractX509TrustManager(trustManagerFactory.getTrustManagers());
            TrustManager[] trustManagers = new TrustManager[]{new CompositeX509TrustManager(defaultTm, customTm)};
            sslContext.init(keyManagers, trustManagers, new java.security.SecureRandom());
            return sslContext;
        } catch (Exception e) {
            throw new IllegalStateException("Failed to initialize ECS SSL context", e);
        }
    }

    private X509TrustManager extractX509TrustManager(TrustManager[] trustManagers) {
        for (TrustManager trustManager : trustManagers) {
            if (trustManager instanceof X509TrustManager x509TrustManager) {
                return x509TrustManager;
            }
        }
        throw new IllegalStateException("No X509TrustManager available");
    }

    private static class CompositeX509TrustManager implements X509TrustManager {
        private final X509TrustManager primary;
        private final X509TrustManager secondary;

        private CompositeX509TrustManager(X509TrustManager primary, X509TrustManager secondary) {
            this.primary = primary;
            this.secondary = secondary;
        }

        @Override
        public void checkClientTrusted(X509Certificate[] chain, String authType) throws CertificateException {
            try {
                primary.checkClientTrusted(chain, authType);
            } catch (CertificateException ignored) {
                secondary.checkClientTrusted(chain, authType);
            }
        }

        @Override
        public void checkServerTrusted(X509Certificate[] chain, String authType) throws CertificateException {
            try {
                primary.checkServerTrusted(chain, authType);
            } catch (CertificateException ignored) {
                secondary.checkServerTrusted(chain, authType);
            }
        }

        @Override
        public X509Certificate[] getAcceptedIssuers() {
            X509Certificate[] primaryIssuers = primary.getAcceptedIssuers();
            X509Certificate[] secondaryIssuers = secondary.getAcceptedIssuers();
            X509Certificate[] merged = new X509Certificate[primaryIssuers.length + secondaryIssuers.length];
            System.arraycopy(primaryIssuers, 0, merged, 0, primaryIssuers.length);
            System.arraycopy(secondaryIssuers, 0, merged, primaryIssuers.length, secondaryIssuers.length);
            return merged;
        }
    }

    private SimpleClientHttpRequestFactory buildRequestFactoryWithoutSsl() {
        SimpleClientHttpRequestFactory factory = new SimpleClientHttpRequestFactory();
        configureFactoryWithTimeoutAndProxy(factory);
        this.restTemplate = buildCaseInsensitiveRestTemplate(factory);
        return factory;
    }

    private void configureFactoryWithTimeoutAndProxy(SimpleClientHttpRequestFactory factory) {
        factory.setConnectTimeout(connectTimeoutMs);
        factory.setReadTimeout(readTimeoutMs);

        if (proxyEnabled && proxyHost != null && !proxyHost.isBlank() && proxyPort > 0) {
            Proxy proxy = new Proxy(Proxy.Type.HTTP, new InetSocketAddress(proxyHost, proxyPort));
            factory.setProxy(proxy);

            if (proxyUsername != null && !proxyUsername.isBlank()) {
                Authenticator.setDefault(new Authenticator() {
                    @Override
                    protected PasswordAuthentication getPasswordAuthentication() {
                        return new PasswordAuthentication(proxyUsername,
                                proxyPassword != null ? proxyPassword.toCharArray() : new char[0]);
                    }
                });
            }
        }
    }

    private RestTemplate buildCaseInsensitiveRestTemplate(SimpleClientHttpRequestFactory factory) {
        RestTemplate template = new RestTemplate(factory);
        List<HttpMessageConverter<?>> converters = template.getMessageConverters();
        for (HttpMessageConverter<?> converter : converters) {
            if (converter instanceof MappingJackson2HttpMessageConverter jacksonConverter) {
                ObjectMapper mapper = jacksonConverter.getObjectMapper().copy();
                mapper.configure(MapperFeature.ACCEPT_CASE_INSENSITIVE_PROPERTIES, true);
                jacksonConverter.setObjectMapper(mapper);
            }
        }
        return template;
    }
}

